// Optical Camouflage - shield harmonic simulation (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var absorb=[8,240,9000], resp=[90,8,0.6];
var bands=["kinetic","thermal","electromagnetic","radiation"];
console.log("Optical Camouflage - absorption by threat band");
console.log("==================================================");
for(var m=0;m<3;m++){
  console.log("Mark "+(m+1)+": peak absorption "+absorb[m]+" MJ, response "+resp[m]+" ms");
  var line=" ";
  for(var b=0;b<bands.length;b++){ var share=(absorb[m]*(0.7+0.1*b)).toFixed(1); line+=bands[b]+"="+share+"MJ "; }
  console.log(line);
}
console.log("Fail-safe rule: shields degrade gracefully, never collapse instantly.");

